#include "kestro.hpp"
#include <iostream>
#include <functional>
#include <thread>
#include <atomic>
#include <sys/wait.h>
using namespace kestro;
int passed=0;
void expect_error(const std::function<void()>&fn){bool error=false;try{fn();}catch(...){error=true;}require(error,"expected failure");}
void test(const std::string&name,const std::function<void()>&fn){fn();std::cout<<"PASS "<<name<<"\n";passed++;}
#include "tests_extra.hpp"
#include "tests06.hpp"
int main(){char pattern[]="/tmp/kestro-native-test-XXXXXX";char*dir=mkdtemp(pattern);require(dir,"mkdtemp failed");std::string root=dir;try{
 test("persistence, versions, atomic conflict and deletes",[&]{auto p=root+"/basic";{Store db(p,true);auto tx=db.commit({{"a","one",0,false},{"b","two",0,false}});require(tx==1&&db.count()==2,"create failed");expect_error([&]{db.commit({{"new","no",ANY,false},{"a","bad",0,false}});});require(!db.get("new").found&&db.get("a").value=="one","partial batch");db.commit({{"a","three",tx,false},{"b","",ANY,true}});db.verify();}{Store db(p);require(db.get("a").value=="three"&&!db.get("b").found,"reopen failed");}});
 test("duplicate transaction keys and limits are rejected",[&]{Store db(root+"/input",true);expect_error([&]{db.commit({{"a","1",ANY,false},{"a","2",ANY,false}});});expect_error([&]{db.commit({{"","x",ANY,false}});});require(db.count()==0,"invalid write applied");});
 test("kernel owner lock rejects second open and hardlink alias",[&]{auto p=root+"/lock";Store db(p,true);expect_error([&]{Store other(p);});auto alias=root+"/alias";require(link(p.c_str(),alias.c_str())==0,"link failed");expect_error([&]{Store other(alias);});});
 test("verified backup refuses overwrite and preserves source",[&]{Store db(root+"/backup-source",true);db.commit({{"a","value",ANY,false}});auto p=root+"/backup";db.snapshot(p);{Store copy(p);copy.verify();require(copy.get("a").value=="value","backup value");}expect_error([&]{db.snapshot(p);});require(db.get("a").value=="value","source changed");});
 test("compaction reclaims history and preserves key versions and transaction ID",[&]{Store db(root+"/compact-source",true);for(int round=0;round<20;round++){std::vector<Op> ops;for(int i=0;i<100;i++)ops.push_back({std::to_string(i),std::string(512,char('a'+round)),ANY,false});db.commit(ops);}db.commit({{"deleted","x",ANY,false}});db.commit({{"deleted","",ANY,true}});auto version=db.get("50").version;auto tx=db.txid();auto p=root+"/compacted";db.snapshot(p,true);{Store compact(p);require(compact.bytes()<db.bytes()/10,"history not reclaimed");require(compact.get("50").version==version&&compact.txid()==tx,"version lost");require(!compact.get("deleted").found,"delete lost");compact.commit({{"50","changed",version,false}});compact.verify();}{Store reopened(p);require(reopened.get("50").value=="changed","checkpoint append replay failed");}});
 test("empty compacted databases can be reopened and written",[&]{Store db(root+"/empty",true);auto p=root+"/empty-copy";db.snapshot(p,true);Store copy(p);copy.commit({{"key","",0,false}});require(copy.get("key").found&&copy.get("key").value.empty(),"empty value failed");copy.verify();});
 test("disk corruption after opening is detected by point reads",[&]{auto p=root+"/damage";Store db(p,true);db.commit({{"key","hello",ANY,false}});FD f(::open(p.c_str(),O_RDWR));unsigned char bad='X';write_at(f.n,&bad,1,START+64+17+3);expect_error([&]{db.get("key");});expect_error([&]{db.verify();});});
 test("committed truncation refuses recovery",[&]{for(int kind=0;kind<1;kind++){auto p=root+"/bad"+std::to_string(kind);uint64_t end;{Store db(p,true);db.commit({{"k","v",ANY,false}});end=db.bytes();}FD f(::open(p.c_str(),O_RDWR));if(!kind){if(ftruncate(f.n,off_t(end-1)))ioerror();}else{unsigned char x=1;write_at(f.n,&x,1,4096+3000);}auto size=file_size(f.n);expect_error([&]{Store db(p);});require(file_size(f.n)==size,"damaged file modified");}});
 test("uncommitted tail is discarded after committed prefix verification",[&]{auto p=root+"/tail";uint64_t end;{Store db(p,true);db.commit({{"k","safe",ANY,false}});end=db.bytes();}FD f(::open(p.c_str(),O_RDWR));Bytes junk(400,127);write_at(f.n,junk.data(),junk.size(),end);Store db(p);require(file_size(f.n)==end&&db.get("k").value=="safe","tail recovery failed");});
 for(const auto&stage:{std::string("after_data"),std::string("after_meta"),std::string("torn_meta"),std::string("sync_error")})test("fault boundary "+stage,[&]{auto p=root+"/crash-"+stage;{Store db(p,true);db.commit({{"acknowledged","safe",ANY,false}});}pid_t pid=fork();require(pid>=0,"fork failed");if(pid==0){setenv("KESTRO_FAULT",stage.c_str(),1);try{Store db(p);try{db.commit({{"pending","maybe",ANY,false}});}catch(...){if(stage!="sync_error")_exit(90);try{db.get("acknowledged");_exit(91);}catch(...){_exit(74);}}_exit(92);}catch(...){_exit(93);}}int status=0;waitpid(pid,&status,0);require(WIFEXITED(status),"child did not exit");int expected=stage=="after_data"?71:stage=="torn_meta"?72:stage=="after_meta"?73:74;require(WEXITSTATUS(status)==expected,"wrong fault exit");{Store db(p);require(db.get("acknowledged").value=="safe","ack lost");require(db.get("pending").found,"a group that reached the file is committed");db.verify();}});
 test("eight parallel reader threads plus a writer preserve valid records",[&]{Store db(root+"/threads",true);std::vector<Op> initial;for(int i=0;i<128;i++)initial.push_back({std::to_string(i),"value",ANY,false});db.commit(initial);std::atomic<bool> stop{false},bad{false};std::vector<std::thread> readers;for(int t=0;t<8;t++)readers.emplace_back([&,t]{try{uint64_t n=t;while(!stop){auto v=db.get(std::to_string(n++%128));if(!v.found||v.value!="value")bad=true;}}catch(...){bad=true;}});for(int i=0;i<200;i++)db.commit({{std::to_string(i%128),"value",ANY,false}});stop=true;for(auto&t:readers)t.join();require(!bad,"concurrent read failed");db.verify();});
 test("deterministic history agrees with reference map after reopen",[&]{auto p=root+"/model";std::unordered_map<std::string,std::string> model;{Store db(p,true);uint64_t state=123;for(int i=0;i<1000;i++){state=state*6364136223846793005ULL+1;auto k=std::to_string((state>>32)%200);bool erase=(state%7)==0;auto v=std::to_string(i);db.commit({{k,v,ANY,erase}});if(erase)model.erase(k);else model[k]=v;}}Store db(p);require(db.count()==model.size(),"model size");for(auto&pair:model)require(db.get(pair.first).value==pair.second,"model mismatch");db.verify();});
 extra_tests(root);
 tests06(root);
 std::cout<<passed<<" tests passed\n";std::filesystem::remove_all(root);return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<" at "<<root<<"\n";return 1;}}
